-- Label existing web summaries with the platform their URL belongs to (see `lib/extract/platforms.ts`).
UPDATE `summaries` SET `source` = 'x' WHERE `source` = 'web' AND (lower(`source_url`) LIKE 'http%://x.com/%' OR lower(`source_url`) LIKE 'http%://%.x.com/%' OR lower(`source_url`) LIKE 'http%://twitter.com/%' OR lower(`source_url`) LIKE 'http%://%.twitter.com/%');--> statement-breakpoint
UPDATE `summaries` SET `source` = 'facebook' WHERE `source` = 'web' AND (lower(`source_url`) LIKE 'http%://facebook.com/%' OR lower(`source_url`) LIKE 'http%://%.facebook.com/%' OR lower(`source_url`) LIKE 'http%://fb.com/%' OR lower(`source_url`) LIKE 'http%://%.fb.com/%' OR lower(`source_url`) LIKE 'http%://fb.watch/%');--> statement-breakpoint
UPDATE `summaries` SET `source` = 'youtube' WHERE `source` = 'web' AND (lower(`source_url`) LIKE 'http%://youtube.com/%' OR lower(`source_url`) LIKE 'http%://%.youtube.com/%' OR lower(`source_url`) LIKE 'http%://youtu.be/%' OR lower(`source_url`) LIKE 'http%://%.youtube-nocookie.com/%');--> statement-breakpoint
UPDATE `summaries` SET `source` = 'github' WHERE `source` = 'web' AND (lower(`source_url`) LIKE 'http%://github.com/%' OR lower(`source_url`) LIKE 'http%://%.github.com/%');
